 To create a decorator for Nest.js middleware that checks the `NODE_ENV` variable and returns `next()` if it's set to `true`, and `false` otherwise, follow these steps:

First, let's define the decorator function named `EnvCheckMiddleware`. This decorator will accept an optional parameter called `allowedEnvValue`, which defaults to `"true"`.

```typescript
import { createParamDecorator, ExecutionContext } from '@nestjs/common';

export const EnvCheckMiddleware = (allowedEnvValue: string = "true") => {
  return CreateContextMiddleware(checkNodeEnv)(allowedEnvValue);
};

function CreateContextMiddleware<T>(fn: Function): PropertyDecorator {
  return (target: Object, propertyKey: string | symbol, descriptor: PropertyDescriptor) => {
    const originalMethod = descriptor.value;

    descriptor.value = async function (...args: any[]) {
      this.req = this.req || this.context.switchToHttp().getRequest();

      if (process.env.NODE_ENV === allowedEnvValue) {
        await fn.apply(this, args);
        return;
      }

      throw new Error('Invalid environment');
    };

    return descriptor;
  };
}

function checkNodeEnv(allowedEnvValue: string = "true"): (req: Request, res: Response, next: NextFunction) => Promise<void> {
  return async (req: Request, res: Response, next: NextFunction) => {
    if (process.env.NODE_ENV === allowedEnvValue) {
      next();
    } else {
      res.status(403).send(false);
    }
  };
}
```

