 To create a simple toast notification using React and the useContextHook, follow these steps:

First, let's create a custom toast context provider. Create a new file named `ToastContext.js`:

```javascript
import { createContext, useState } from 'react';

export const ToastContext = createContext();

export const ToastProvider = ({ children }) => {
  const [message, setMessage] = useState(null);

  const addToast = (newMessage) => {
    setMessage(newMessage);
    setTimeout(() => setMessage(null), 3000); // hide toast after 3 seconds
  };

  return (
    <ToastContext.Provider value={{ addToast }}>
      {children}
      {message && <div className="toast">{message}</div>}
    </ToastContext.Provider>
  );
};
```

