import axios from "axios";

interface Option {
  value: string;
  label: string;
}

const EmailInput: React.FC = () => {
  const [items, setItems] = useState<Option[]>([]);

  const {
    isOpen,
    getMenuProps,
    getComboBoxProps,
    getToggleButtonProps,
    getInputProps,
    highlightedIndex,
    getItemProps,
  } = useCombobox({
    items,
    onInputValueChange: debounce((inputValue) => {
      if (inputValue.length > 2) {
        searchEmails(inputValue).then((data) => setItems(data));
      }
    }, 500),
  });

  const searchEmails = async (prefix: string): Promise<Option[]> => {
